import {Game,FIGHTERS,MOVES} from './engine.mjs';
const $=id=>document.getElementById(id),preview=$('preview'),pc=preview.getContext('2d'),canvas=$('game'),ctx=canvas.getContext('2d');
const atlas=new Image(),stage=new Image();atlas.src='assets/fighters.png';stage.src='assets/shrine.png';
let selected=0,opponent=1,mode='arcade',game=null,screen='lobby',ambience=0,arcadeMatch=1,particles=[],shake=0,hitstop=0,time=0,last=0,muted=true,audio=null,nextBeat=0,trainingAI=false;
let settings={difficulty:'normal',volume:.35,shake:true},stats={wins:0,matches:0,bestCombo:0};try{settings={...settings,...JSON.parse(localStorage.getItem('dojo-settings')||'{}')};stats={...stats,...JSON.parse(localStorage.getItem('dojo-stats')||'{}')};}catch{}
const keys=new Set(),touch=new Set();const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),2500);}
function save(){try{localStorage.setItem('dojo-stats',JSON.stringify(stats));localStorage.setItem('dojo-settings',JSON.stringify(settings));}catch{}}
function initAudio(){if(!audio)try{audio=new (window.AudioContext||window.webkitAudioContext)();}catch{}audio?.resume();}
function tone(freq,duration=.1,type='square',gain=.08,slide=0){if(muted||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(20,freq+slide),audio.currentTime+duration);g.gain.setValueAtTime(gain*settings.volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
function noise(duration=.13,gain=.2){if(muted||!audio)return;const b=audio.createBuffer(1,audio.sampleRate*duration,audio.sampleRate),data=b.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const src=audio.createBufferSource(),g=audio.createGain();src.buffer=b;g.gain.value=gain*settings.volume;src.connect(g);g.connect(audio.destination);src.start();}
function music(){if(muted||!audio||screen!=='fight'||game?.paused||audio.currentTime<nextBeat)return;nextBeat=audio.currentTime+.24;const notes=[55,55,82.41,55,65.41,55,73.42,82.41];music.beat=(music.beat||0)+1;tone(notes[music.beat%8],.15,'triangle',.08);if(music.beat%2===0)tone(110,.08,'sine',.14,-70);if(music.beat%4===2)noise(.06,.055);}
function sprite(c,id,pose,x,y,w=215,h=240,face=1,alpha=1){if(!atlas.complete||!atlas.naturalWidth)return;c.save();c.imageSmoothingEnabled=false;c.globalAlpha=alpha;c.translate(Math.round(x),Math.round(y));c.scale(face,1);const sw=atlas.naturalWidth/6,sh=atlas.naturalHeight/4;c.drawImage(atlas,pose*sw,id*sh,sw,sh,Math.round(-w/2),Math.round(-h),w,h);c.restore();}
function drawScene(c,t){c.imageSmoothingEnabled=false;c.fillStyle='#151020';c.fillRect(0,0,960,540);if(stage.complete&&stage.naturalWidth){c.save();if(ambience===1)c.filter='hue-rotate(35deg) saturate(.85)';if(ambience===2)c.filter='hue-rotate(170deg) brightness(.85)';c.drawImage(stage,0,0,960,540);c.restore();}else{c.fillStyle='#251b38';c.fillRect(0,0,960,430);c.fillStyle='#18131f';c.fillRect(0,430,960,110);}c.fillStyle='#b1a9e022';for(let i=0;i<65;i++){const x=(i*137+t*48)%1000,y=(i*79+t*350)%540;c.fillRect(Math.round(x),Math.round(y),1,9);}c.fillStyle='#ff989b';for(let i=0;i<12;i++){const x=(i*97+t*12)%1000,y=90+(i*37+t*20)%270;c.globalAlpha=.3;c.fillRect(x,y,3,2);}c.globalAlpha=1;}
function shadow(c,x,y=454){c.fillStyle='#05051175';c.beginPath();c.ellipse(x,y,48,9,0,0,Math.PI*2);c.fill();}
function poseFor(f){if(f.state==='hit')return 4;if(f.move){const m=MOVES[f.move];return f.moveTime<m.startup?0:f.moveTime<m.startup+m.active+.07?m.pose:1;}if(f.state==='walk')return Math.floor(f.walk)%2?1:0;if(game?.phase==='done'||game?.phase==='roundEnd'&&game.winner===game.fighters.indexOf(f))return 5;return 0;}
function drawFighter(c,f,t){shadow(c,f.x);const pose=poseFor(f),bob=f.move||f.stun?0:Math.sin(t*7+f.id)*2;const sy=462-f.y+bob;if(f.heatTime>0){for(let i=3;i>0;i--)sprite(c,f.id,pose,f.x-f.face*i*20,sy,235,245,f.face,.1);}c.save();if(f.flash>0)c.filter='brightness(2.5)';if(f.block){c.fillStyle='#acdfff3b';c.strokeStyle='#acdfff';c.lineWidth=2;c.beginPath();c.ellipse(f.x+f.face*38,sy-120,24,73,0,0,Math.PI*2);c.fill();c.stroke();}sprite(c,f.id,pose,f.x,sy,235,f.block?232:245,f.face);c.restore();if(f.move&&f.moveTime>MOVES[f.move].startup-.03&&f.moveTime<MOVES[f.move].startup+.12){c.save();c.translate(f.x+f.face*50,sy-100);c.scale(f.face,1);c.strokeStyle=f.move==='heat'?FIGHTERS[f.id].color:'#fff4d7';c.globalAlpha=.65;c.lineWidth=f.move==='heat'?7:3;c.beginPath();c.arc(0,0,f.move==='kick'?77:55,-.6,.65);c.stroke();c.restore();}if(f.hp<=25){c.fillStyle=FIGHTERS[f.id].color;c.globalAlpha=.35+.25*Math.sin(t*13);for(let i=0;i<7;i++)c.fillRect(f.x-45+i*15,sy-15-(t*80+i*21)%80,3,8);c.globalAlpha=1;}}
function burst(x,y,color,heavy=false,block=false){for(let i=0;i<(heavy?42:20);i++){const a=Math.random()*Math.PI*2,s=70+Math.random()*(heavy?400:240);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.15+Math.random()*.35,max:.5,color:block?'#acdfff':i%3===0?'#fff4cb':color,size:heavy?5:3});}particles.push({x,y,ring:true,life:.2,max:.2,color:block?'#acdfff':color,heavy});}
function onEvent(e){if(e.type==='hit'||e.type==='block'){burst(e.x,e.y,e.color,e.heavy,e.type==='block');if(settings.shake)shake=e.heavy?12:4;hitstop=e.heavy?.065:.035;noise(e.heavy?.22:.1,e.type==='block'?.1:.25);tone(e.heavy?70:135,.12,'sawtooth',.1,-50);if(e.i===0&&e.type==='hit'){stats.bestCombo=Math.max(stats.bestCombo,e.combo);if(e.combo>=2){$('combo-label').textContent=`${e.combo} HIT COMBO\n${e.damage} DAMAGE`;clearTimeout(onEvent.comboTimer);onEvent.comboTimer=setTimeout(()=>$('combo-label').textContent='',1000);}}}if(e.type==='heat'){burst(e.x,370,FIGHTERS[game.fighters[e.i].id].color,true);tone(100,.5,'sawtooth',.16,700);}if(e.type==='noheat'&&e.i===0)toast('HEAT : remplissez la jauge en attaquant.');if(e.type==='fight'){tone(330,.15,'square',.15);tone(660,.25,'square',.12);}if(e.type==='roundEnd'){noise(.3,.25);tone(80,.6,'sawtooth',.12,-45);keys.clear();touch.clear();}if(e.type==='land')burst(e.x,455,'#9f85a9');if(e.type==='matchEnd')finish(e.winner);}
function selectFighter(id){selected=id;const f=FIGHTERS[id];$('fighter-index').textContent=`0${id+1} / 04`;$('fighter-first').textContent=f.first;$('fighter-last').textContent=f.last;$('fighter-tag').textContent=f.tag;$('fighter-origin').textContent=f.origin;$('fighter-description').textContent=f.description;$('fighter-style').textContent=f.style;['power','speed','range'].forEach(s=>{$('stat-'+s).innerHTML=Array.from({length:5},(_,i)=>`<i class="stat-segment ${i<f[s]?'filled':''}"></i>`).join('');});document.querySelectorAll('.fighter-card').forEach((el,i)=>{el.classList.toggle('selected',id===i);el.setAttribute('aria-pressed',String(id===i));el.querySelector('.card-selected').textContent=id===i?'P1 SELECTED':'';});if(opponent===selected){opponent=(selected+1)%4;$('opponent').value=opponent;}tone(480+id*80,.05,'square',.05);}
function createRoster(){FIGHTERS.forEach((f,i)=>{const b=document.createElement('button');b.className='fighter-card';b.dataset.kanji=f.kanji;b.setAttribute('aria-label',`${f.first} ${f.last}`);b.innerHTML=`<span class="card-index">0${i+1} / ${f.origin}</span><span class="card-name">${f.first}<br>${f.last}</span><span class="card-style">${f.style}</span><span class="card-selected"></span><canvas width="220" height="250"></canvas>`;b.onclick=()=>selectFighter(i);$('roster').append(b);const o=document.createElement('option');o.value=i;o.textContent=f.first+' '+f.last;$('opponent').append(o);});$('opponent').value=opponent;selectFighter(0);}
function drawCards(){document.querySelectorAll('.fighter-card canvas').forEach((el,i)=>{const c=el.getContext('2d');c.clearRect(0,0,220,250);sprite(c,i,0,110,248,230,250);});}atlas.onload=drawCards;atlas.onerror=()=>toast('Chargement des sprites impossible. Actualisez la page.');createRoster();
function startMatch(reset=true){initAudio();keys.clear();touch.clear();if(reset)arcadeMatch=1;game=new Game({p1:selected,p2:opponent,mode,difficulty:settings.difficulty,onEvent});game.trainingAI=trainingAI;if(mode==='training')game.fighters.forEach(f=>f.heat=100);screen='fight';particles=[];hitstop=0;shake=0;$('lobby').classList.add('hidden');$('fight').classList.remove('hidden');$('pause-overlay').classList.add('hidden');$('result-overlay').classList.add('hidden');$('training-strip').classList.toggle('hidden',mode!=='training');$('p1-name').textContent=(FIGHTERS[selected].first+' '+FIGHTERS[selected].last).trim();$('p2-name').textContent=(FIGHTERS[opponent].first+' '+FIGHTERS[opponent].last).trim();$('p2-type').textContent=mode==='versus'?'PLAYER 02':'CPU';$('match-label').textContent=mode==='arcade'?`ARCADE / MATCH 0${arcadeMatch} SUR 03`:mode==='versus'?'VERSUS / DUEL LOCAL':'DOJO / ENTRAÎNEMENT LIBRE';$('combo-label').textContent='';window.scrollTo({top:0,behavior:'instant'});}
function lobby(){screen='lobby';game=null;keys.clear();touch.clear();$('fight').classList.add('hidden');$('lobby').classList.remove('hidden');$('pause-overlay').classList.add('hidden');$('result-overlay').classList.add('hidden');selectFighter(selected);}
function finish(winner){stats.matches++;if(winner===0)stats.wins++;save();$('result-overlay').classList.remove('hidden');$('result-title').textContent=winner===0?'VICTORY':winner===1?'DEFEAT':'DRAW';const name=FIGHTERS[game.fighters[Math.max(0,winner)].id].first;$('result-description').textContent=winner===-1?'Égalité. Le prochain duel vous départagera.':`${name} remporte le match ${game.wins[0]} – ${game.wins[1]}. `+(mode==='arcade'&&winner===0&&arcadeMatch===3?'Tournoi terminé. Vous êtes le King of Iron Fist !':'Chaque combat est une nouvelle leçon.');$('result-kicker').textContent=mode==='arcade'&&winner===0&&arcadeMatch===3?'KING OF IRON FIST':'MATCH TERMINÉ';$('rematch').textContent=mode==='arcade'&&winner===0&&arcadeMatch<3?'ADVERSAIRE SUIVANT →':'REJOUER →';}
function pause(value){if(!game||game.phase==='done')return;game.paused=value;$('pause-overlay').classList.toggle('hidden',!value);keys.clear();touch.clear();}
function updateHUD(){game.fighters.forEach((f,i)=>{const prefix='p'+(i+1);$(prefix+'-health').style.width=f.hp+'%';$(prefix+'-ghost').style.width=f.hp+'%';$(prefix+'-heat').style.width=f.heat+'%';$(prefix+'-rounds').textContent=Array.from({length:2},(_,n)=>game.wins[i]>n?'●':'○').join(' ');});$('timer').textContent=mode==='training'?'∞':String(Math.ceil(game.time)).padStart(2,'0');$('round').textContent=mode==='training'?'FREE PLAY':`ROUND 0${game.round}`;let banner='';if(game.phase==='intro')banner=game.phaseTime<1.25?`ROUND ${game.round}`:'FIGHT!';if(game.phase==='roundEnd')banner=game.fighters.some(f=>f.hp===0)?'K.O.':'TIME UP';$('game-banner').textContent=banner;}
function render(dt){time+=dt;if(screen==='lobby'){drawScene(pc,time);shadow(pc,545);const f={id:selected,x:545,y:0,state:'idle',hp:100,stun:0,flash:0,heatTime:0,face:1};sprite(pc,selected,Math.floor(time/5)%2===1&&time%5<.3?2:0,545,478+Math.sin(time*6)*2,370,370);pc.fillStyle=FIGHTERS[selected].color;pc.globalAlpha=.15;pc.fillRect(440,474,210,2);pc.globalAlpha=1;}else if(game){if(hitstop>0)hitstop-=dt;else game.update(dt,[{left:keys.has('KeyQ')||keys.has('KeyA')||touch.has('left'),right:keys.has('KeyD')||touch.has('right'),block:keys.has('KeyS')||touch.has('block')},{left:keys.has('ArrowLeft'),right:keys.has('ArrowRight'),block:keys.has('ArrowDown')}]);ctx.save();if(shake>0&&!game.paused){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake=Math.max(0,shake-dt*42);}drawScene(ctx,time);[...game.fighters].sort((a,b)=>a.y-b.y).forEach(f=>drawFighter(ctx,f,time));if(!game.paused){particles.forEach(p=>{p.life-=dt;if(!p.ring){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;}ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.strokeStyle=p.color;if(p.ring){ctx.lineWidth=p.heavy?5:2;ctx.beginPath();ctx.arc(p.x,p.y,(1-p.life/p.max)*(p.heavy?85:50),0,Math.PI*2);ctx.stroke();}else ctx.fillRect(Math.round(p.x),Math.round(p.y),p.size,p.size);});particles=particles.filter(p=>p.life>0);}ctx.globalAlpha=1;ctx.restore();updateHUD();music();}}
function loop(now){const dt=Math.min((now-last)/1000||.016,.05);last=now;render(dt);requestAnimationFrame(loop);}requestAnimationFrame(loop);
const actionKeys={KeyJ:[0,'jab'],KeyK:[0,'kick'],KeyL:[0,'upper'],KeyU:[0,'heat'],KeyZ:[0,'jump'],KeyW:[0,'jump'],Space:[0,'jump'],Numpad1:[1,'jab'],Numpad2:[1,'kick'],Numpad3:[1,'upper'],Numpad0:[1,'heat'],Digit1:[1,'jab'],Digit2:[1,'kick'],Digit3:[1,'upper'],Digit0:[1,'heat'],ArrowUp:[1,'jump']};
window.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('modal').open)return;if(e.code==='Escape'){e.preventDefault();if(screen==='fight')pause(!game.paused);return;}if(screen==='lobby'){if(e.code==='ArrowRight')selectFighter((selected+1)%4);if(e.code==='ArrowLeft')selectFighter((selected+3)%4);if(e.code==='Enter')startMatch();return;}if(screen==='fight'&&(actionKeys[e.code]||['KeyQ','KeyA','KeyD','KeyS','ArrowLeft','ArrowRight','ArrowDown'].includes(e.code))){e.preventDefault();keys.add(e.code);if(!e.repeat&&actionKeys[e.code]){const [i,a]=actionKeys[e.code];if(i===0||mode==='versus')game.action(i,a);}}});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();touch.clear();if(screen==='fight')pause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden&&screen==='fight')pause(true);});
document.querySelectorAll('[data-hold],[data-action]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);initAudio();if(b.dataset.hold)touch.add(b.dataset.hold);if(b.dataset.action)game?.action(0,b.dataset.action);});const release=()=>{if(b.dataset.hold)touch.delete(b.dataset.hold);};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);});
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(t=>t.classList.toggle('selected',t===b));});$('opponent').onchange=e=>opponent=Number(e.target.value);$('start').onclick=()=>startMatch();$('back-lobby').onclick=lobby;$('pause').onclick=()=>pause(true);$('resume').onclick=()=>pause(false);$('restart').onclick=()=>startMatch(false);$('quit').onclick=lobby;$('result-quit').onclick=lobby;$('rematch').onclick=()=>{if(mode==='arcade'&&game.winner===0&&arcadeMatch<3){arcadeMatch++;opponent=(selected+arcadeMatch)%4;startMatch(false);}else startMatch();};$('stage-switch').onclick=()=>{ambience=(ambience+1)%3;toast(['Ambiance : clair de lune','Ambiance : brume pourpre','Ambiance : nuit électrique'][ambience]);};$('training-reset').onclick=()=>{game.resetFighters();game.fighters.forEach(f=>f.heat=100);particles=[];toast('Positions et jauges réinitialisées.');};$('training-ai').onclick=()=>{trainingAI=!trainingAI;game.trainingAI=trainingAI;$('training-ai').textContent='IA : '+(trainingAI?'ON':'OFF');};
function sound(){initAudio();muted=!muted;$('sound-state').textContent=muted?'OFF':'ON';$('sound-toggle').setAttribute('aria-label',muted?'Activer le son':'Couper le son');tone(660,.1,'square',.1);}$('sound-toggle').onclick=sound;$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Le plein écran est indisponible dans ce navigateur.');}};
function modal(content){if(screen==='fight'&&game.phase!=='done')pause(true);$('modal-content').innerHTML=content;$('modal').showModal();}function closeModal(){$('modal').close();}$('modal-close').onclick=closeModal;$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal();});
const row=(label,key)=>`<div class="guide-row"><span>${label}</span><span>${key.split(' ').map(k=>`<kbd>${k}</kbd>`).join('')}</span></div>`;
function guide(){modal(`<span class="eyebrow">LE DOJO / GUIDE DE COMBAT</span><h2 class="modal-title">MASTER YOUR MOVES.</h2><div class="guide-grid"><div><h3>JOUEUR 01</h3>${row('Déplacement','Q D')}${row('Saut','Z')}${row('Garde (maintenir)','S')}${row('Poing rapide','J')}${row('Coup de pied','K')}${row('Launcher / uppercut','L')}${row('Heat Burst','U')}</div><div><h3>JOUEUR 02</h3>${row('Déplacement','← →')}${row('Saut','↑')}${row('Garde (maintenir)','↓')}${row('Poing rapide','1')}${row('Coup de pied','2')}${row('Launcher / uppercut','3')}${row('Heat Burst','0')}</div></div><p class="modal-note"><b>La victoire :</b> remportez 2 rounds. Chaque round dure 60 secondes.<br><b>Les combos :</b> approchez, puis enchaînez J → J → K ou L → J → K dès la fin de chaque attaque. Le launcher projette l'adversaire en l'air.<br><b>Heat Burst :</b> les coups donnés et reçus remplissent la jauge bleue. À 100 %, appuyez sur U pour une attaque puissante.<br><b>Astuce :</b> maintenez S pour réduire les dégâts, puis punissez l'adversaire pendant sa récupération. Les touches A / W fonctionnent aussi sur un clavier QWERTY. Échap met le jeu en pause.</p>`);}
$('nav-guide').onclick=guide;$('help-link').onclick=guide;$('nav-play').onclick=lobby;$('nav-stats').onclick=()=>modal(`<span class="eyebrow">VOTRE PARCOURS / SAUVEGARDE LOCALE</span><h2 class="modal-title">FIGHTER RECORD.</h2><div class="score-grid"><div><strong>${stats.matches}</strong><span>MATCHS JOUÉS</span></div><div><strong>${stats.wins}</strong><span>VICTOIRES P1</span></div><div><strong>${stats.bestCombo}</strong><span>MEILLEUR COMBO</span></div></div><p class="modal-note">Votre progression reste enregistrée dans ce navigateur. Continuez à combattre pour améliorer votre record.</p>`);
$('nav-settings').onclick=()=>{modal(`<span class="eyebrow">AJUSTEZ VOTRE EXPÉRIENCE</span><h2 class="modal-title">GAME SETTINGS.</h2><label class="settings-row">Difficulté de l'IA<select id="difficulty"><option value="easy">Facile</option><option value="normal">Normale</option><option value="hard">Difficile</option></select></label><label class="settings-row">Volume<input id="volume" aria-label="Volume" type="range" min="0" max="1" step=".05" value="${settings.volume}"></label><label class="settings-row">Secousses d'impact<input id="shake-option" type="checkbox" ${settings.shake?'checked':''}></label><p class="modal-note">La difficulté s'applique au prochain match. Le son s'active avec le bouton SON en haut de l'écran.</p>`);$('difficulty').value=settings.difficulty;$('difficulty').onchange=e=>{settings.difficulty=e.target.value;save();};$('volume').oninput=e=>{settings.volume=Number(e.target.value);save();};$('shake-option').onchange=e=>{settings.shake=e.target.checked;save();};};
// Read-only game snapshot for browser QA and integrations.
window.dojo={getState:()=>({screen,selected,mode,phase:game?.phase,paused:game?.paused,time:game?.time,wins:game?.wins,fighters:game?.fighters.map(f=>({id:f.id,x:f.x,y:f.y,hp:f.hp,heat:f.heat,state:f.state}))})};
